<script lang="ts">let { values = [], width = 120, height = 28 }: { values?: number[]; width?: number; height?: number } = $props();let points = $derived.by(() => { if (values.length === 0) return ''; const max = Math.max(...values, 1); return values.map((v, i) => `${(i / Math.max(1, values.length - 1)) * width},${height - (v / max) * (height - 2) - 1}`).join(' '); });</script><svg {width} {height} role="img"><polyline {points} fill="none" stroke="var(--accent)" stroke-width="1.5" /></svg><style>svg{background:var(--bg-2);border-radius:var(--radius-sm)}</style>
